module web.title_length
  purpose: Expose a tool that reports how many characters a web page's title has.

import std.http as web exposing Url

public type TitleError is one of
  FetchFailed(detail: Text)
  NoTitle(detail: Text)
end

function title_length(html: Text)
  returns Integer
  or fails with TitleError
  purpose: Count the characters in the first title element of an HTML text.
  tags: html, text
  example: title_length("<html><head><title>Hello</title></head></html>") is 5
  example: title_length("<TITLE lang=\"en\"> Renyi </TITLE>") is 5

  let lower be html.to_lower()
  let open_at be lower.index_of("<title") otherwise fail with NoTitle(detail: "the page has no title element")
  let after_open be html.drop(open_at)
  let tag_end be after_open.index_of(">") otherwise fail with NoTitle(detail: "the title tag is never closed with a greater-than sign")
  let content be after_open.drop(tag_end + 1)
  let close_at be content.to_lower().index_of("</title>") otherwise fail with NoTitle(detail: "the title element has no closing tag")
  let title be content.take(close_at)
  return title.trim().length()
end

public function page_title_length(url: Url)
  returns Integer
  or fails with TitleError
  needs network.http
  purpose: Download the web page at the given address and return the number of characters in its title element, failing with NoTitle when the page has none.
  tags: web, html, title
  expose as tool

  let page be web.get(url) otherwise fail with FetchFailed(detail: "the page could not be downloaded")
  return title_length(page)
end
